import numpy as np

class WavySphere:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Base sphere term
        sphere_term = np.sum(x**2)

        # Wavy perturbation terms
        wavy_terms = 0.0
        for i in range(self.dim):
            wavy_terms += np.sin(5 * x[i]) * np.exp(-0.1 * x[i]**2)

        # Combine terms with scaling
        return sphere_term + 0.5 * wavy_terms
